{
  "code": "ORDER_APPROVAL",
  "name": "Order Approval Workflow",
  "description": "Multi-level approval workflow for orders",
  "version": "1.0",
  "states": [
    {
      "code": "DRAFT",
      "name": "Draft",
      "type": "START",
      "isInitial": true
    },
    {
      "code": "PENDING_MANAGER",
      "name": "Pending Manager Approval",
      "type": "APPROVAL"
    },
    {
      "code": "PENDING_DIRECTOR",
      "name": "Pending Director Approval",
      "type": "APPROVAL"
    },
    {
      "code": "APPROVED",
      "name": "Approved",
      "type": "END"
    },
    {
      "code": "REJECTED",
      "name": "Rejected",
      "type": "END"
    }
  ],
  "transitions": [
    {
      "name": "Submit for Approval",
      "fromState": "DRAFT",
      "toState": "PENDING_MANAGER",
      "requiresApproval": false
    },
    {
      "name": "Manager Approve",
      "fromState": "PENDING_MANAGER",
      "toState": "PENDING_DIRECTOR",
      "requiresApproval": true,
      "approverRole": "MANAGER"
    },
    {
      "name": "Manager Reject",
      "fromState": "PENDING_MANAGER",
      "toState": "REJECTED",
      "requiresApproval": true,
      "approverRole": "MANAGER"
    },
    {
      "name": "Director Approve",
      "fromState": "PENDING_DIRECTOR",
      "toState": "APPROVED",
      "requiresApproval": true,
      "approverRole": "DIRECTOR"
    },
    {
      "name": "Director Reject",
      "fromState": "PENDING_DIRECTOR",
      "toState": "REJECTED",
      "requiresApproval": true,
      "approverRole": "DIRECTOR"
    }
  ]
}

{
  "transitionName": "Submit for Approval",
